def detectar_columna_texto(df):
    candidatos = ["texto", "text", "tweet", "tweets", "content", "sentence", "review"]
    for c in candidatos:
        if c in df.columns:
            return c
    obj_cols = [c for c in df.columns if df[c].dtype == "object"]
    if obj_cols:
        return obj_cols[0]
